    }
    .nav-links a:hover { color: var(--black); }
    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .btn-ghost {
      background: none;
      border: none;
      font-family: var(--font);
      font-size: 14px;
      font-weight: 500;
      color: var(--gray-600);
      cursor: pointer;
      transition: color 0.2s;
    }
    .btn-ghost:hover { color: var(--black); }
    .btn-primary {
      background: var(--black);
      color: var(--white);
      border: none;
      font-family: var(--font);
      font-size: 14px;
      font-weight: 600;
      padding: 9px 18px;
      border-radius: 8px;
      cursor: pointer;
      transition: background 0.2s, transform 0.15s;
