  <script>
    // Stats Counter Animation
    function animateCounter(el, target, duration = 2000) {
      const start = 0;
      const startTime = performance.now();

      function easeOutQuart(t) {
        return 1 - Math.pow(1 - t, 4);
      }

      function update(currentTime) {
        const elapsed = currentTime - startTime;
        const progress = Math.min(elapsed / duration, 1);
        const easedProgress = easeOutQuart(progress);
        const current = Math.floor(start + (target - start) * easedProgress);

        el.textContent = current.toLocaleString();

        if (progress < 1) {
          requestAnimationFrame(update);
        } else {
          el.textContent = target.toLocaleString();
        }
      }

      requestAnimationFrame(update);
    }

    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const counters = entry.target.querySelectorAll('.stat-number');
          counters.forEach((counter, index) => {
            setTimeout(() => {
              animateCounter(counter, parseInt(counter.dataset.target));
            }, index * 150);
          });
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.3 });

    const statsSection = document.getElementById('stats');
    if (statsSection) statsObserver.observe(statsSection);

    // Search Tabs
    const searchTabs = document.getElementById('search-tabs');
    if (searchTabs) {
      searchTabs.addEventListener('click', (e) => {
        const tab = e.target.closest('.tab');
        if (!tab) return;

        searchTabs.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');

        const tabName = tab.dataset.tab;
        document.querySelectorAll('.tab-content').forEach(content => {
          content.classList.toggle('active', content.dataset.content === tabName);
        });
      });
    }

    // Filter Pills
    const filterPills = document.getElementById('filter-pills');
    if (filterPills) {
      filterPills.addEventListener('click', (e) => {
        const pill = e.target.closest('.pill');
        if (!pill) return;

        filterPills.querySelectorAll('.pill').forEach(p => p.classList.remove('active'));
        pill.classList.add('active');
      });
    }

    // Flows Toggle
    const flowsToggle = document.getElementById('flows-toggle');
    if (flowsToggle) {
      flowsToggle.addEventListener('click', (e) => {
        const btn = e.target.closest('.toggle-btn');
        if (!btn) return;

        flowsToggle.querySelectorAll('.toggle-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        const toggleName = btn.dataset.toggle;
        document.querySelectorAll('.flows-content').forEach(content => {
          content.classList.toggle('active', content.dataset.flow === toggleName);
        });
      });
    }
  </script>
